import{_ as t,o as r,c as a,a2 as d}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"Kostenlose Cloud","description":"MiniTavern kostenlose Cloud-APIs — Free-/Trial-Kontingente und dauerhaft kostenlose Modelle, BYOK-Verbindung; Einstieg ohne bezahlten Key.","frontmatter":{"title":"Kostenlose Cloud","description":"MiniTavern kostenlose Cloud-APIs — Free-/Trial-Kontingente und dauerhaft kostenlose Modelle, BYOK-Verbindung; Einstieg ohne bezahlten Key.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"Kostenlose Cloud · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern kostenlose Cloud-APIs — Free-/Trial-Kontingente und dauerhaft kostenlose Modelle, BYOK-Verbindung; Einstieg ohne bezahlten Key."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/free-cloud"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/free-cloud"}]]},"headers":[],"relativePath":"de/free-cloud/index.md","filePath":"de/free-cloud/index.md","lastUpdated":1787224147000}'),n={name:"de/free-cloud/index.md"};function o(i,e,l,s,h,g){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="kostenlose-cloud" tabindex="-1">Kostenlose Cloud <a class="header-anchor" href="#kostenlose-cloud" aria-label="Permalink to &quot;Kostenlose Cloud&quot;">​</a></h1><p>MiniTavern ist <strong>BYOK (Bring Your Own Key)</strong>: Es gibt kein Cloud-Kontingent von der App — Sie registrieren API Keys bei Anbietern oder Inference-Plattformen selbst.<br> Diese Seite fasst <strong>übliche Free-/Trial-Kontingente</strong> und die App-Konfiguration zusammen. Kontingente und Policies ändern sich — <strong>maßgeblich ist die Live-Anzeige in den jeweiligen Konsolen</strong>.</p><blockquote><p>Sicherheit: Ein API Key ist wie ein Passwort. Nur in der lokalen App-Speicherung hinterlegen — nicht in Chats, Screenshots oder öffentlichen Repos teilen.</p></blockquote><h2 id="zuerst-den-schnellsten-pfad-wahlen" tabindex="-1">Zuerst den schnellsten Pfad wählen <a class="header-anchor" href="#zuerst-den-schnellsten-pfad-wahlen" aria-label="Permalink to &quot;Zuerst den schnellsten Pfad wählen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ihre Situation</th><th>Empfehlung</th><th>App-Plattform</th></tr></thead><tbody><tr><td>Festlandchina, schnell chatten</td><td><a href="#zhipu-ai-glm">Zhipu Flash (kostenlos)</a> oder <a href="#siliconflow">SiliconFlow Free</a></td><td>Custom (OpenAI)</td></tr><tr><td>Ein Key für Text + Bild (multimodal)</td><td><a href="/ultra_guides/de/free-cloud/agnes-ai">Agnes AI</a></td><td>Custom (OpenAI) / Images</td></tr><tr><td>Ein Key für GPT / Gemini <code>*-free</code> + Bild</td><td><a href="/ultra_guides/de/free-cloud/aihubmix">AIHubMix</a></td><td>Custom (OpenAI) / Images</td></tr><tr><td>Coding-Gateway, befristete Free-Textmodelle</td><td><a href="/ultra_guides/de/free-cloud/opencode-zen">OpenCode Zen</a></td><td>Custom (OpenAI)</td></tr><tr><td>Offizielle chinesische LLMs (Trial)</td><td><a href="#qwen--alibaba-cloud-bailian">Qwen · Alibaba Bailian</a></td><td>Qwen</td></tr><tr><td>Reasoning / Code</td><td><a href="#deepseek">DeepSeek</a></td><td>DeepSeek</td></tr><tr><td>Overseas-Account, multimodaler Text</td><td><a href="#google-gemini">Google Gemini</a></td><td>Gemini(Google)</td></tr><tr><td>Ein Key für viele freie Open-Source-Modelle</td><td><a href="/ultra_guides/de/free-cloud/openrouter">OpenRouter <code>:free</code></a></td><td>OpenRouter</td></tr><tr><td>Weitere Free-Anbieter</td><td><a href="/ultra_guides/de/free-cloud/freellm">FreeLLM-Verzeichnis</a> (<a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a>)</td><td>siehe Verzeichnis</td></tr><tr><td>Sehr schnelle Open-Source-Inference</td><td><a href="#groq">Groq</a></td><td>Custom (OpenAI)</td></tr><tr><td>Keine Cloud</td><td><a href="/ultra_guides/de/local/">Lokale Modelle</a></td><td>Custom (OpenAI)</td></tr></tbody></table><p>Allgemeine Key-Schritte: <a href="/ultra_guides/de/manual/model-link">Modellverbindung</a>. Lokal: <a href="/ultra_guides/de/local/">Lokale Modelle</a> · <a href="/ultra_guides/de/quickstart">30-Minuten-Quickstart</a>.</p><h2 id="so-tragen-sie-es-in-minitavern-ein" tabindex="-1">So tragen Sie es in MiniTavern ein <a class="header-anchor" href="#so-tragen-sie-es-in-minitavern-ein" aria-label="Permalink to &quot;So tragen Sie es in MiniTavern ein&quot;">​</a></h2><p>Pfad: <strong>Einstellungen → Modelle → Modellverbindung → Neu</strong></p><ol><li>Richtige <strong>Modellplattform</strong> wählen (Spalte „App-Plattform“).</li><li><strong>API Key</strong> einfügen; bei Custom zusätzlich <strong>Base URL</strong>.</li><li><strong>Modell-ID</strong> wählen oder tippen (exakt wie in der Herstellerdoku, Groß-/Kleinschreibung beachten).</li><li><strong>Testen</strong> → bei Erfolg als <strong>Standard</strong> setzen.</li></ol><table tabindex="0"><thead><tr><th>Anbieter</th><th>App-Plattform</th><th>Base URL (üblich)</th><th>Hinweis</th></tr></thead><tbody><tr><td>Gemini</td><td>Gemini(Google)</td><td>Voreinstellung</td><td>Gemini-Protokoll — nicht als OpenAI eintragen</td></tr><tr><td>OpenRouter</td><td>OpenRouter</td><td>Voreinstellung</td><td>Free-IDs oft mit <code>:free</code></td></tr><tr><td>Qwen / Bailian</td><td>Qwen</td><td>Voreinstellung (Intl. umschaltbar)</td><td><strong>Allgemeinen</strong> API Key nutzen, keinen Coding-Plan-Key</td></tr><tr><td>DeepSeek</td><td>DeepSeek</td><td>Voreinstellung</td><td></td></tr><tr><td>Zhipu / SiliconFlow / Agnes / AIHubMix / Zen / Groq / Mistral u. a.</td><td><strong>Custom (OpenAI)</strong></td><td>siehe Abschnitte</td><td>OpenAI-kompatibles Gateway</td></tr></tbody></table><hr><h2 id="haufig-in-china-direktzugang-festland" tabindex="-1">Häufig in China (Direktzugang Festland) <a class="header-anchor" href="#haufig-in-china-direktzugang-festland" aria-label="Permalink to &quot;Häufig in China (Direktzugang Festland)&quot;">​</a></h2><h3 id="zhipu-ai-glm" tabindex="-1">Zhipu AI (GLM) <a class="header-anchor" href="#zhipu-ai-glm" aria-label="Permalink to &quot;Zhipu AI (GLM)&quot;">​</a></h3><p>Geeignet für: <strong>dauerhaft kostenlosen</strong> Chat (Flash-Serie), gute chinesische Roleplay-Qualität.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Website / Key</td><td><a href="https://open.bigmodel.cn" target="_blank" rel="noreferrer">open.bigmodel.cn</a> → Konsole → API Keys</td></tr><tr><td>Free</td><td>Permanente Free-Modelle wie <code>GLM-*-Flash</code>; neue Nutzer oft Extra-Trial (Konsole)</td></tr><tr><td>Kreditkarte</td><td>meist nicht nötig</td></tr><tr><td>Base URL</td><td><code>https://open.bigmodel.cn/api/paas/v4</code></td></tr><tr><td>Modellbeispiele</td><td><code>glm-4.5-flash</code>, <code>glm-4.7-flash</code> (Namen im Model Plaza prüfen)</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><p>Ablauf: registrieren → API Key → Custom (OpenAI) → Base URL + Key → Flash-ID → Verbindung testen.</p><h3 id="siliconflow" tabindex="-1">SiliconFlow <a class="header-anchor" href="#siliconflow" aria-label="Permalink to &quot;SiliconFlow&quot;">​</a></h3><p>Geeignet für: ein Key für viele Open-Source-Chatmodelle; teils Free-Bildmodelle.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Website / Key</td><td><a href="https://cloud.siliconflow.cn" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a> → Konto → API-Schlüssel</td></tr><tr><td>Free</td><td><strong>Free-Modelle</strong> ohne Abrechnung (Name ohne <code>Pro/</code>-Präfix); nach Realname alle Free-Modelle</td></tr><tr><td>Limits</td><td>feste RPM/TPM je Modell; <a href="https://docs.siliconflow.cn/cn/userguide/rate-limits/rate-limit-and-upgradation" target="_blank" rel="noreferrer">Rate Limits</a></td></tr><tr><td>Base URL</td><td><code>https://api.siliconflow.cn/v1</code></td></tr><tr><td>Modellbeispiele</td><td>Plaza-Tag „免费“, z. B. <code>Qwen/Qwen3-8B</code> (Liste ändert sich)</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><p>Achtung: gleiches Modell oft als Free und <code>Pro/...</code> (kostenpflichtig). Falsche ID = Kosten. Free-Verbrauch in der Rechnung sollte 0 sein.</p><h3 id="qwen-·-alibaba-cloud-bailian" tabindex="-1">Qwen · Alibaba Cloud Bailian <a class="header-anchor" href="#qwen-·-alibaba-cloud-bailian" aria-label="Permalink to &quot;Qwen · Alibaba Cloud Bailian&quot;">​</a></h3><p>Geeignet für: offizielle Qwen-Serie; MiniTavern hat <strong>Qwen</strong>-Preset.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Aktivierung</td><td><a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">Bailian-Konsole</a> (Nordchina 2 / Peking), Vertrag akzeptieren</td></tr><tr><td>Free</td><td><strong>Neukunden-Token</strong>: oft ca. <strong>1 Mio. Token / Modell</strong>, ca. <strong>90 Tage</strong>; Kontingente nicht übertragbar</td></tr><tr><td>Key</td><td>Bailian → API-Key; <strong>allgemeinen Key</strong> (Token-/Coding-Plan-Keys <strong>verbrauchen kein</strong> Free-Kontingent)</td></tr><tr><td>App</td><td><strong>Qwen</strong> (CN-Preset; Intl. umschaltbar)</td></tr><tr><td>Kostenstopp</td><td>„<strong>Bei aufgebrauchtem Free-Kontingent stoppen</strong>“ in der Konsole aktivieren</td></tr></tbody></table><p>Offiziell: <a href="https://help.aliyun.com/zh/model-studio/new-free-quota" target="_blank" rel="noreferrer">Neukunden-Free-Quota</a>. Nach Ablauf entstehen Kosten.</p><p>Bildgenerierung (Wanxiang / Qwen-Image): <strong>Einstellungen → Bildgenerierung → Bildverbindung → Qwen</strong>, wenn das Modell im Free-Kontingent ist.</p><h3 id="deepseek" tabindex="-1">DeepSeek <a class="header-anchor" href="#deepseek" aria-label="Permalink to &quot;DeepSeek&quot;">​</a></h3><p>Geeignet für: Reasoning, lange Texte, gutes Preis-Leistungs-Verhältnis — <strong>nicht dauerhaft 0 €</strong>.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Website / Key</td><td><a href="https://platform.deepseek.com" target="_blank" rel="noreferrer">platform.deepseek.com</a> → API Keys</td></tr><tr><td>Free</td><td>oft <strong>Startguthaben / Trial</strong> (Betrag laut Konsole)</td></tr><tr><td>App</td><td><strong>DeepSeek</strong></td></tr><tr><td>Modellbeispiele</td><td><code>deepseek-v4-flash</code>, <code>deepseek-v4-pro</code> (<a href="https://api-docs.deepseek.com/zh-cn/" target="_blank" rel="noreferrer">Doku</a>)</td></tr></tbody></table><p>Nach Guthaben: Pay-as-you-go; ohne Saldo schlagen Requests fehl.</p><h3 id="modelscope-api-inference" tabindex="-1">ModelScope API-Inference <a class="header-anchor" href="#modelscope-api-inference" aria-label="Permalink to &quot;ModelScope API-Inference&quot;">​</a></h3><p>Geeignet für: Alibaba-Realname vorhanden, Community-Open-Source-Inference.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Token</td><td><a href="https://modelscope.cn" target="_blank" rel="noreferrer">modelscope.cn</a> → Zugriffstoken</td></tr><tr><td>Free</td><td>Tages-Request-Quota (<a href="https://modelscope.cn/docs/model-service/API-Inference/limits" target="_blank" rel="noreferrer">Limits</a>)</td></tr><tr><td>Base URL</td><td><code>https://api-inference.modelscope.cn/v1</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><hr><h2 id="international-aggregatoren" tabindex="-1">International / Aggregatoren <a class="header-anchor" href="#international-aggregatoren" aria-label="Permalink to &quot;International / Aggregatoren&quot;">​</a></h2><h3 id="agnes-ai" tabindex="-1">Agnes AI <a class="header-anchor" href="#agnes-ai" aria-label="Permalink to &quot;Agnes AI&quot;">​</a></h3><p>Ein Free-Key für <strong>Text und Bild</strong> (Flash Free). Video: Website; App hat noch keinen Video-Einstieg.</p><p>Details: <strong><a href="/ultra_guides/de/free-cloud/agnes-ai">Agnes AI</a></strong>.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Website / Key</td><td><a href="https://agnes-ai.com/" target="_blank" rel="noreferrer">agnes-ai.com</a> · <a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>Free</td><td>Free Access: Flash Text/Bild (RPM-Limits)</td></tr><tr><td>Base URL</td><td><code>https://apihub.agnes-ai.com/v1</code></td></tr><tr><td>Text</td><td><code>agnes-2.5-flash</code></td></tr><tr><td>Bild</td><td><code>agnes-image-2.1-flash</code> (<strong>Custom (OpenAI Images)</strong>)</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong> / <strong>Custom (OpenAI Images)</strong></td></tr></tbody></table><h3 id="opencode-zen" tabindex="-1">OpenCode Zen <a class="header-anchor" href="#opencode-zen" aria-label="Permalink to &quot;OpenCode Zen&quot;">​</a></h3><p>Free-Textmodelle auf dem OpenCode-Gateway (z. B. <code>mimo-v2.5-free</code>). Flagship meist Pay-as-you-go — Autotop-up prüfen.</p><p>Details: <strong><a href="/ultra_guides/de/free-cloud/opencode-zen">OpenCode Zen</a></strong>.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Website / Key</td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a> · <a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">Docs</a></td></tr><tr><td>Free</td><td>Modelle mit Free in der Preisliste (innerhalb Caps)</td></tr><tr><td>Base URL</td><td><code>https://opencode.ai/zen/v1</code></td></tr><tr><td>Text</td><td><code>mimo-v2.5-free</code>, <code>hy3-free</code>, <code>big-pickle</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong> (chat/completions-kompatible IDs)</td></tr></tbody></table><h3 id="aihubmix" tabindex="-1">AIHubMix <a class="header-anchor" href="#aihubmix" aria-label="Permalink to &quot;AIHubMix&quot;">​</a></h3><p>Ein Key für gesponserte <code>*-free</code>-Modelle (GPT / Gemini / GLM …) und <strong>GPT-Image-2-free</strong>; oft ohne Karte.</p><p>Details: <strong><a href="/ultra_guides/de/free-cloud/aihubmix">AIHubMix</a></strong>.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Website / Key</td><td><a href="https://aihubmix.com" target="_blank" rel="noreferrer">aihubmix.com</a> · <a href="https://docs.aihubmix.com/cn/blogs/free-ai-models" target="_blank" rel="noreferrer">Free-Modelle</a></td></tr><tr><td>Free</td><td>IDs enden auf <code>-free</code>; RPM / Tageskontingent je Modell</td></tr><tr><td>Base URL</td><td><code>https://aihubmix.com/v1</code></td></tr><tr><td>Text</td><td><code>gpt-4o-free</code>, <code>gpt-5.5-free</code>, <code>coding-glm-5.1-free</code></td></tr><tr><td>Bild</td><td><code>gpt-image-2-free</code> (<strong>Custom (OpenAI Images)</strong>)</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong> / <strong>Custom (OpenAI Images)</strong></td></tr></tbody></table><h3 id="google-gemini" tabindex="-1">Google Gemini <a class="header-anchor" href="#google-gemini" aria-label="Permalink to &quot;Google Gemini&quot;">​</a></h3><p>Multimodaler Text, langer Kontext; <strong>Text</strong>-Free-Tier oft großzügig.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer">aistudio.google.com/app/apikey</a></td></tr><tr><td>Free</td><td>Teile Gemini Flash / Lite <strong>Text</strong> (RPM / RPD in AI Studio)</td></tr><tr><td>Kreditkarte</td><td>Text-Free meist ohne; <strong>neuere Bild-APIs oft ohne Free tier</strong></td></tr><tr><td>Region</td><td>EU / UK / CH ggf. ohne Free</td></tr><tr><td>Privacy</td><td>Free-Prompts können zur Produktverbesserung genutzt werden</td></tr><tr><td>App</td><td><strong>Gemini(Google)</strong></td></tr></tbody></table><p>Chat: Textmodelle (z. B. <code>gemini-flash-latest</code>). Keine IDs mit <code>tts</code> / <code>image</code> — Test erwartet TEXT; TTS liefert AUDIO → <code>response modalities (TEXT) is not supported</code>.</p><p><code>HTTP 404</code> + <code>no longer available to new users</code>: ID offline / nicht für neue Nutzer (z. B. <code>gemini-2.5-flash-lite</code>). Liste aktualisieren, online Flash/Lite wählen (z. B. <code>gemini-flash-latest</code>).</p><p><code>HTTP 429</code> + <code>generate_content_free_tier_requests</code> (oft Limit 20): Free RPM erschöpft — laut <code>Please retry in …</code> warten. <a href="https://ai.dev/rate-limit" target="_blank" rel="noreferrer">ai.dev/rate-limit</a>.</p><p>Bild: Gemini-<strong>App</strong> vs. <strong>Developer API</strong> unterschiedlich; API-Bildmodelle oft ohne Free. Typisch: Chat mit Gemini, Bild lokal A1111/ComfyUI — <a href="/ultra_guides/de/local/image-gen/">Bildmodelle lokal</a>.</p><h3 id="openrouter" tabindex="-1">OpenRouter <a class="header-anchor" href="#openrouter" aria-label="Permalink to &quot;OpenRouter&quot;">​</a></h3><p>Ein Key für viele <strong>Open-Source-/Drittanbieter-Free-Pools</strong>; IDs oft <code>:free</code>. Details: <strong><a href="/ultra_guides/de/free-cloud/openrouter">OpenRouter</a></strong>.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>Free</td><td><code>:free</code> / Collection Free; ca. 20 RPM, begrenzte Tagesrequests; Aufladen kann Tageslimit erhöhen</td></tr><tr><td>App</td><td><strong>OpenRouter</strong></td></tr><tr><td>Beispiele</td><td><code>openrouter/free</code>, <code>meta-llama/llama-3.3-70b-instruct:free</code>, <code>openai/gpt-oss-20b:free</code></td></tr><tr><td>Collections</td><td><a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a> · <a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a></td></tr></tbody></table><p>Hinweis: Free-Upstream kann Prompts für Training speichern. <code>HTTP 429: Provider returned error</code> → anderes <code>:free</code>, später erneut, oder <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">BYOK</a>.</p><h3 id="groq" tabindex="-1">Groq <a class="header-anchor" href="#groq" aria-label="Permalink to &quot;Groq&quot;">​</a></h3><p>Sehr <strong>niedrige Latenz</strong> für Open-Source-Inference.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer">console.groq.com/keys</a></td></tr><tr><td>Free</td><td>dauerhafter Free tier (RPM / RPD / TPM, ändert sich)</td></tr><tr><td>Kreditkarte</td><td>meist nicht nötig</td></tr><tr><td>Base URL</td><td><code>https://api.groq.com/openai/v1</code></td></tr><tr><td>Beispiele</td><td><code>llama-3.1-8b-instant</code>, <code>llama-3.3-70b-versatile</code>, <code>openai/gpt-oss-20b</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><h3 id="mistral-ai" tabindex="-1">Mistral AI <a class="header-anchor" href="#mistral-ai" aria-label="Permalink to &quot;Mistral AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://console.mistral.ai/api-keys" target="_blank" rel="noreferrer">console.mistral.ai/api-keys</a></td></tr><tr><td>Free</td><td>Experiment / Trial (Monats-Token laut Konsole); Prompts ggf. zur Verbesserung</td></tr><tr><td>Base URL</td><td><code>https://api.mistral.ai/v1</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><h3 id="cerebras-sambanova-u-a" tabindex="-1">Cerebras / SambaNova u. a. <a class="header-anchor" href="#cerebras-sambanova-u-a" aria-label="Permalink to &quot;Cerebras / SambaNova u. a.&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Plattform</th><th>Key</th><th>Base URL</th><th>Hinweis</th></tr></thead><tbody><tr><td>Cerebras</td><td><a href="https://cloud.cerebras.ai/" target="_blank" rel="noreferrer">cloud.cerebras.ai</a></td><td><code>https://api.cerebras.ai/v1</code></td><td>Free oft mit Tages-Token-Cap; ggf. Zahlungsmethode</td></tr><tr><td>SambaNova</td><td><a href="https://cloud.sambanova.ai/apis" target="_blank" rel="noreferrer">cloud.sambanova.ai</a></td><td><code>https://api.sambanova.ai/v1</code></td><td>dauerhafter Free + gelegentliches Guthaben; enge Limits</td></tr></tbody></table><p>App: <strong>Custom (OpenAI)</strong>; Modellnamen laut Konsole.</p><h3 id="github-models" tabindex="-1">GitHub Models <a class="header-anchor" href="#github-models" aria-label="Permalink to &quot;GitHub Models&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Einstieg</td><td><a href="https://github.com/marketplace/models" target="_blank" rel="noreferrer">GitHub Models</a></td></tr><tr><td>Auth</td><td>GitHub Personal Access Token</td></tr><tr><td>Base URL</td><td><code>https://models.github.ai/inference</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr><tr><td>Limits</td><td>RPM / RPD je Modell — leichtes Trial</td></tr></tbody></table><h3 id="nvidia-nim" tabindex="-1">NVIDIA NIM <a class="header-anchor" href="#nvidia-nim" aria-label="Permalink to &quot;NVIDIA NIM&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td>Einstieg</td><td><a href="https://build.nvidia.com/explore/discover" target="_blank" rel="noreferrer">build.nvidia.com</a></td></tr><tr><td>Base URL</td><td><code>https://integrate.api.nvidia.com/v1</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong> (falls Nvidia-Preset wieder verfügbar: optional)</td></tr></tbody></table><hr><h2 id="trial-kontingente-nicht-dauerhaft-free" tabindex="-1">Trial-Kontingente (nicht dauerhaft free) <a class="header-anchor" href="#trial-kontingente-nicht-dauerhaft-free" aria-label="Permalink to &quot;Trial-Kontingente (nicht dauerhaft free)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Anbieter</th><th>Typisch</th><th>App</th></tr></thead><tbody><tr><td>OpenAI</td><td>gelegentliches Trial-Guthaben; <strong>kein stabiles Free-Tier</strong> am Haupt-API</td><td>ChatGPT(OpenAI)</td></tr><tr><td>Anthropic Claude</td><td>Starter Credits, schnell weg</td><td>Claude(Anthropic)</td></tr><tr><td>DeepSeek</td><td>siehe Startguthaben oben</td><td>DeepSeek</td></tr><tr><td>Alibaba Bailian</td><td>Neukunden-Token (~90 Tage)</td><td>Qwen</td></tr></tbody></table><p>Danach Autoload-Risiko senken: Key löschen, „Stop bei 0 Free“ aktivieren, oder Free-/Lokal-Backend wählen.</p><hr><h2 id="kostenlose-bildgenerierung" tabindex="-1">Kostenlose Bildgenerierung <a class="header-anchor" href="#kostenlose-bildgenerierung" aria-label="Permalink to &quot;Kostenlose Bildgenerierung&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pfad</th><th>Kosten</th><th>Hinweis</th></tr></thead><tbody><tr><td><a href="/ultra_guides/de/local/image-gen/">Lokal A1111 / ComfyUI</a></td><td>Strom + GPU</td><td>unbegrenzte Anzahl; Handy → PC-LAN</td></tr><tr><td>SiliconFlow Free-Bildmodelle</td><td>0 bei Free-ID</td><td>Bildverbindung <strong>Custom (OpenAI Images)</strong>, Base URL wie Silicon <code>…/v1</code></td></tr><tr><td><a href="/ultra_guides/de/free-cloud/agnes-ai">Agnes AI</a> Image Flash</td><td>Free Access</td><td><strong>Custom (OpenAI Images)</strong>, <code>https://apihub.agnes-ai.com/v1</code>, z. B. <code>agnes-image-2.1-flash</code></td></tr><tr><td><a href="/ultra_guides/de/free-cloud/aihubmix">AIHubMix</a></td><td><code>*-free</code> Bild</td><td><strong>Custom (OpenAI Images)</strong>, <code>https://aihubmix.com/v1</code>, z. B. <code>gpt-image-2-free</code></td></tr><tr><td>Wanxiang / Qwen Image</td><td>Bailian-Kontingent prüfen</td><td><strong>Einstellungen → Bildgenerierung → Bildverbindung → Qwen</strong></td></tr><tr><td>OpenAI / viele Gemini Image APIs</td><td>meist bezahlt</td><td>nicht als „kostenlose Bild-API“ planen</td></tr></tbody></table><p>Chat- und Bildverbindung getrennt möglich: z. B. Chat Zhipu Flash, Bild heimisches ComfyUI.</p><hr><h2 id="tipps-fehlerbehebung" tabindex="-1">Tipps &amp; Fehlerbehebung <a class="header-anchor" href="#tipps-fehlerbehebung" aria-label="Permalink to &quot;Tipps &amp; Fehlerbehebung&quot;">​</a></h2><ol><li><strong>Erst testen, dann chatten</strong>: bei Fehler „Details“ → <a href="/ultra_guides/de/manual/errors">Fehlercodes</a>.</li><li><strong>429 / Rate limit</strong>: leichteres Modell, kürzerer Kontext, oder zweites Free-Backend.</li><li><strong>Unerwartete Kosten</strong>: <code>Pro/</code>-Modell? Bailian ohne Stopp? Trial leer?</li><li><strong>Privacy</strong>: Free-Tiers erlauben oft Log-Training — Sensibles besser <a href="/ultra_guides/de/local/">lokal</a>.</li><li><strong>Kontingentänderungen</strong>: Zahlen hier sind Richtwerte; Live-Konsole gilt. Mehr Index: <a href="/ultra_guides/de/free-cloud/freellm">FreeLLM</a> (<a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a> · <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a>).</li></ol><h2 id="verwandte-kapitel" tabindex="-1">Verwandte Kapitel <a class="header-anchor" href="#verwandte-kapitel" aria-label="Permalink to &quot;Verwandte Kapitel&quot;">​</a></h2><ul><li><a href="/ultra_guides/de/manual/model-link">Modellverbindung</a> — Eintrag in der App</li><li><a href="/ultra_guides/de/manual/getting-started">Erste Schritte</a></li><li><a href="/ultra_guides/de/free-cloud/freellm">FreeLLM-Verzeichnis</a></li><li><a href="/ultra_guides/de/local/">Lokale Modelle</a></li><li><a href="/ultra_guides/de/local/image-gen/">Bildmodelle lokal</a> — A1111 / ComfyUI</li></ul>',82)])])}const p=t(n,[["render",o]]);export{u as __pageData,p as default};
